import{_ as a,o as e,c as r,a2 as n}from"./chunks/framework.mRCPFc5l.js";const b=JSON.parse('{"title":"性能与加载体验","description":"用用户可感知的指标拆解加载、交互和更新过程，优先优化真正影响体验的路径。","frontmatter":{"title":"性能与加载体验","description":"用用户可感知的指标拆解加载、交互和更新过程，优先优化真正影响体验的路径。"},"headers":[],"relativePath":"web/frontend/performance.md","filePath":"web/frontend/performance.md","lastUpdated":1786262003000}'),d={name:"web/frontend/performance.md"};function s(l,t,i,o,p,h){return e(),r("div",null,[...t[0]||(t[0]=[n(`<h1 id="性能与加载体验" tabindex="-1">性能与加载体验 <a class="header-anchor" href="#性能与加载体验" aria-label="Permalink to &quot;性能与加载体验&quot;">​</a></h1><p>性能不是一次性跑分，而是用户从打开页面到完成任务的等待感受。优化前先确认瓶颈发生在资源加载、主线程执行、接口响应还是页面更新。</p><h2 id="先观察用户路径" tabindex="-1">先观察用户路径 <a class="header-anchor" href="#先观察用户路径" aria-label="Permalink to &quot;先观察用户路径&quot;">​</a></h2><p>把页面拆成三个阶段：</p><ol><li><strong>首次可见</strong>：关键内容何时出现，用户是否知道页面正在做什么。</li><li><strong>可以交互</strong>：点击、输入和滚动是否及时响应。</li><li><strong>数据更新</strong>：请求结束后，页面是否平滑地呈现成功、空数据或失败状态。</li></ol><p>只压缩某个资源，不一定能改善关键路径。首屏不需要的图表、编辑器和大图片应延后加载，而不是与主内容争抢网络和解析时间。</p><h2 id="优先级高于-把所有资源做小" tabindex="-1">优先级高于“把所有资源做小” <a class="header-anchor" href="#优先级高于-把所有资源做小" aria-label="Permalink to &quot;优先级高于“把所有资源做小”&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>处理原则</th></tr></thead><tbody><tr><td>首屏文字和关键样式</td><td>尽早可用，减少阻塞</td></tr><tr><td>路由后才出现的模块</td><td>按路由或交互懒加载</td></tr><tr><td>图片与媒体</td><td>提供尺寸，使用合适格式，屏外延迟加载</td></tr><tr><td>列表数据</td><td>分页、虚拟滚动或逐段加载</td></tr><tr><td>第三方脚本</td><td>审核必要性，避免阻塞主线程</td></tr></tbody></table><h2 id="让等待状态有方向" tabindex="-1">让等待状态有方向 <a class="header-anchor" href="#让等待状态有方向" aria-label="Permalink to &quot;让等待状态有方向&quot;">​</a></h2><p>加载骨架应接近最终布局，避免数据到达时页面大幅跳动；慢操作提供可取消、可重试或继续填写的路径。错误提示要说明下一步，而不是只写“加载失败”。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>正在加载成员列表…     正常等待</span></span>
<span class="line"><span>没有符合条件的成员     空结果，可调整筛选</span></span>
<span class="line"><span>连接超时，可重新加载   可恢复失败</span></span></code></pre></div><h2 id="优化前后都要验证" tabindex="-1">优化前后都要验证 <a class="header-anchor" href="#优化前后都要验证" aria-label="Permalink to &quot;优化前后都要验证&quot;">​</a></h2><ul><li>用真实或接近真实的数据量测试，不能只看三条列表项。</li><li>模拟慢网络与低性能设备，观察主操作是否仍可完成。</li><li>记录优化前后的关键指标和用户路径，避免“感觉变快了”的判断。</li><li>不为小幅分数变化破坏可维护性；复杂优化要有明确收益和回滚方式。</li></ul><p>好的性能工作让用户少等待、少困惑，也让团队更容易知道下一步该优化哪里。</p>`,14)])])}const u=a(d,[["render",s]]);export{b as __pageData,u as default};
